 "content": "from collections import deque


def _normalize(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    board_w = 0
    while board_w < w and grid[0][board_w] == frame:
        board_w += 1

    # Identify the colored shapes to the right of the framed board.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(board_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and board_w <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects.append((color, _normalize(cells)))

    out = [row[:board_w] for row in grid]
    boundaries = [r for r in range(h) if all(grid[r][c] == frame for c in range(board_w))]
    for top, bottom in zip(boundaries, boundaries[1:]):
        holes = [(r - top - 1, c - 1)
                 for r in range(top + 1, bottom)
                 for c in range(1, board_w - 1)
                 if grid[r][c] == 0]
        if not holes:
            continue
        pattern = _normalize(holes)
        matches = [color for color, shape in objects if shape == pattern]
        if len(matches) != 1:
            raise ValueError(f"Expected one matching object for {pattern}, found {matches}")
        color = matches[0]
        for r in range(top + 1, bottom):
            for c in range(1, board_w - 1):
                if grid[r][c] == 0:
                    out[r][c] = color
    return out


